#include <queue>
#include <vector>

class TreeNode {
public:
    int value;
    double frequency;
    TreeNode* left;
    TreeNode* right;
    TreeNode(int val, double freq) : value(val), frequency(freq), left(nullptr), right(nullptr) {}
};

struct CompareTreeNode {
    bool operator()(TreeNode* a, TreeNode* b) {
        return a->frequency > b->frequency;
    }
};

TreeNode* huffmanBuildTree(int values[], double freqs[], int size) {
    std::priority_queue<TreeNode*, std::vector<TreeNode*>, CompareTreeNode> minHeap;

    // Create a TreeNode for each value-frequency pair and add it to the min-heap
    for (int i = 0; i < size; ++i) {
        minHeap.push(new TreeNode(values[i], freqs[i]));
    }

    // Build the Huffman tree
    while (minHeap.size() > 1) {
        TreeNode* left = minHeap.top();
        minHeap.pop();
        TreeNode* right = minHeap.top();
        minHeap.pop();

        TreeNode* parent = new TreeNode(-1, left->frequency + right->frequency);
        parent->left = left;
        parent->right = right;
        minHeap.push(parent);
    }

    return minHeap.top();
}

